import{_ as a,c as t,o as i,aj as l}from"./chunks/framework.CDhdelVI.js";const m=JSON.parse(`{"title":"Margot's Midwest Thin (Deck)","description":"Low-hydration, cold-fermented, sheeted-thin Colorado-style pizza with olive oil and malt for crisp snap and controlled blistering.","frontmatter":{"title":"Margot's Midwest Thin (Deck)","description":"Low-hydration, cold-fermented, sheeted-thin Colorado-style pizza with olive oil and malt for crisp snap and controlled blistering.","head":[["meta",{"name":"description","content":"Low-hydration, cold-fermented, sheeted-thin Colorado-style pizza with olive oil and malt for crisp snap and controlled blistering."}],["meta",{"property":"og:title","content":"Margot's Midwest Thin (Deck)"}],["meta",{"property":"og:description","content":"Low-hydration, cold-fermented, sheeted-thin Colorado-style pizza with olive oil and malt for crisp snap and controlled blistering."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/margots-midwest-thin-deck-pizza.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Margot's Midwest Thin (Deck)"}],["meta",{"name":"twitter:description","content":"Low-hydration, cold-fermented, sheeted-thin Colorado-style pizza with olive oil and malt for crisp snap and controlled blistering."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/margots-midwest-thin-deck-pizza.html"}]]},"headers":[],"relativePath":"recipes/margots-midwest-thin-deck-pizza.md","filePath":"recipes/margots-midwest-thin-deck-pizza.md"}`),r={name:"recipes/margots-midwest-thin-deck-pizza.md"};function o(n,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="margot-s-midwest-thin-deck" tabindex="-1">Margot&#39;s Midwest Thin (Deck) <a class="header-anchor" href="#margot-s-midwest-thin-deck" aria-label="Permalink to “Margot&#39;s Midwest Thin (Deck)”">​</a></h1><p>This is a Fargo&#39;s-style Midwest thin preset: low hydration, strong flour, long cold fermentation, rolled thin, and baked hot for crisp snap. Use the <a href="https://kitchenratio.com/calculator" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined.</p></div><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>This recipe comes from long-term hands-on experience, plus a few adjustments that make it more practical at home.</p><p>The original dough ran at a much <strong>lower hydration</strong>, closer to a cracker-style texture, which worked well with a commercial dough sheeter. For home baking, a small hydration lift improves:</p><ul><li>Extensibility</li><li>Handling (without a sheeter)</li><li>Crust texture while keeping the signature snap</li></ul><p>This version is currently set to <strong>48% hydration</strong> to preserve the thin, crisp Midwest deck profile while still handling cleanly at home.</p><h2 id="baker-s-testing-range" tabindex="-1">Baker&#39;s % (Testing Range) <a class="header-anchor" href="#baker-s-testing-range" aria-label="Permalink to “Baker&#39;s % (Testing Range)”">​</a></h2><ul><li><strong>Bread flour (12.5-13% protein)</strong> - 100%</li><li><strong>Water</strong> - 48%</li><li><strong>Salt</strong> - 1.8%</li><li><strong>Corn oil</strong> - 1.5%</li><li><strong>Diastatic malt powder</strong> - 0.5%</li><li><strong>Instant dry yeast</strong> - 0.30%</li></ul><h2 id="optional-scrap-old-dough-carryover" tabindex="-1">Optional: Scrap / Old Dough Carryover <a class="header-anchor" href="#optional-scrap-old-dough-carryover" aria-label="Permalink to “Optional: Scrap / Old Dough Carryover”">​</a></h2><ul><li><strong>Old dough</strong> - 5-10% of total dough weight</li><li>If using old dough, reduce yeast to <strong>0.25%</strong></li><li>Old dough is not added as baker&#39;s % flour. It replaces part of total dough weight.</li><li>See <a href="/guides/preferments.html#pate-fermentee-pate-fermentee">Pate fermentee (Pâte fermentée)</a> for method details.</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Bread flour</strong> - 1000g (100%)</li><li><strong>Water</strong> - 480g (48%)</li><li><strong>Salt</strong> - 18g (1.8%)</li><li><strong>Corn oil</strong> - 15g (1.5%)</li><li><strong>Diastatic malt powder</strong> - 5g (0.5%)</li><li><strong>Instant dry yeast</strong> - 3g (0.30%)</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>No sugar and no docking for this style.</p></div><h2 id="style-characteristics" tabindex="-1">Style Characteristics <a class="header-anchor" href="#style-characteristics" aria-label="Permalink to “Style Characteristics”">​</a></h2><ul><li>Low hydration</li><li>Strong flour</li><li>Long cold fermentation</li><li>Sheeted thin</li><li>Cornmeal-stacked skins</li><li>500F rotating deck equivalent</li><li>No sugar</li><li>No docking</li></ul><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="day-1-mix" tabindex="-1">Day 1 - Mix <a class="header-anchor" href="#day-1-mix" aria-label="Permalink to “Day 1 - Mix”">​</a></h3><ul><li>Combine water, yeast, and diastatic malt.</li><li>Rest 5 minutes (especially for active dry yeast).</li><li>Add flour and mix until shaggy.</li><li>Add corn oil slowly.</li><li>Add salt during final 2-3 minutes.</li><li>Mix total <strong>12-15 minutes</strong>.</li></ul><h3 id="dough-feel-target" tabindex="-1">Dough Feel Target <a class="header-anchor" href="#dough-feel-target" aria-label="Permalink to “Dough Feel Target”">​</a></h3><ul><li>Stiff</li><li>Smooth</li><li>Resistant</li><li>Not soft</li><li>Slight sheen from oil</li></ul><h3 id="day-1-cold-first-ferment" tabindex="-1">Day 1 - Cold First Ferment <a class="header-anchor" href="#day-1-cold-first-ferment" aria-label="Permalink to “Day 1 - Cold First Ferment”">​</a></h3><ul><li>Lightly oil container.</li><li>Place dough inside.</li><li>Refrigerate immediately.</li><li>Cold ferment <strong>8 hours</strong>.</li></ul><h3 id="day-1-punch-and-reset" tabindex="-1">Day 1 - Punch and Reset <a class="header-anchor" href="#day-1-punch-and-reset" aria-label="Permalink to “Day 1 - Punch and Reset”">​</a></h3><ul><li>Remove from fridge.</li><li>Punch down firmly (full degas).</li><li>Return to fridge overnight (<strong>12-18 hours</strong>).</li></ul><h3 id="day-2-divide-and-roll" tabindex="-1">Day 2 - Divide and Roll <a class="header-anchor" href="#day-2-divide-and-roll" aria-label="Permalink to “Day 2 - Divide and Roll”">​</a></h3><ul><li>Keep dough cold.</li><li>Divide to <strong>10 oz (283g)</strong> for an 11-inch pizza.</li><li>Roll with pin (do not stretch).</li><li>Target thickness: <strong>2-2.5 mm</strong> (about 1/8 inch).</li></ul><h3 id="cut-and-stack" tabindex="-1">Cut and Stack <a class="header-anchor" href="#cut-and-stack" aria-label="Permalink to “Cut and Stack”">​</a></h3><ul><li>Trim to clean 11-inch circle.</li><li>Dust lightly with cornmeal.</li><li>Stack skins (max 10).</li><li>Refrigerate <strong>24-48 hours</strong>.</li><li>This hold creates the signature snap.</li></ul><h3 id="bake-day-oven-setup" tabindex="-1">Bake Day - Oven Setup <a class="header-anchor" href="#bake-day-oven-setup" aria-label="Permalink to “Bake Day - Oven Setup”">​</a></h3><ul><li>Use stone or steel.</li><li>Preheat <strong>550F</strong> for <strong>45-60 minutes</strong>.</li></ul><h3 id="bake-process" tabindex="-1">Bake Process <a class="header-anchor" href="#bake-process" aria-label="Permalink to “Bake Process”">​</a></h3><ul><li>Pull skin from fridge.</li><li>Sauce immediately.</li><li>Add light toppings.</li><li>Launch onto stone or steel.</li></ul><h3 id="during-bake" tabindex="-1">During Bake <a class="header-anchor" href="#during-bake" aria-label="Permalink to “During Bake”">​</a></h3><ul><li>At <strong>60-90 seconds</strong>, pop center bubbles.</li><li>Rotate at <strong>3-4 minutes</strong>.</li></ul><h3 id="total-bake-time" tabindex="-1">Total Bake Time <a class="header-anchor" href="#total-bake-time" aria-label="Permalink to “Total Bake Time”">​</a></h3><ul><li><strong>Steel</strong>: 5-6 minutes</li><li><strong>Stone</strong>: 7-8 minutes</li></ul><h2 id="dough-ball-reference-11-inch" tabindex="-1">Dough Ball Reference (11-Inch) <a class="header-anchor" href="#dough-ball-reference-11-inch" aria-label="Permalink to “Dough Ball Reference (11-Inch)”">​</a></h2><table tabindex="0"><thead><tr><th>Weight</th><th>Style outcome</th></tr></thead><tbody><tr><td>9 oz</td><td>Extra crisp</td></tr><tr><td>10 oz</td><td>Classic Fargo&#39;s balance</td></tr><tr><td>11 oz</td><td>Slightly more chew</td></tr></tbody></table><h2 id="technical-notes" tabindex="-1">Technical Notes <a class="header-anchor" href="#technical-notes" aria-label="Permalink to “Technical Notes”">​</a></h2><ul><li>Diastatic malt supports browning in this no-sugar dough.</li><li>Scrap carryover improves flavor stability over repeated cycles.</li><li>Lower hydration requires strong flour and benefits from cold handling.</li><li>Process is tuned to emulate a ~500F rotating deck environment.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/yield-planner.html">Yield Planner</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/colorado-pizza-dough.html">Colorado Style Pizza Dough</a></li><li><a href="/recipes/new-york-style-pizza.html">New York Style Pizza (Home-Oven Optimized)</a></li></ul><hr><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',51)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
